def settle_up(balances: dict[str, int]) -> tuple[Transfer, ...]:
    # Step 1: Validate input
    total = sum(balances.values())
    if total != 0:
        raise ValueError('unbalanced')

    non_zero = {k: v for k, v in balances.items() if v != 0}
    if len(non_zero) > MAX_SETTLEMENT_MEMBERS:
        raise ValueError('too many members')

    if not non_zero:
        return ()

    # Step 2: Partition into zero-sum groups, maximizing the number of groups
    members = list(non_zero.keys())
    n = len(members)

    # Generate all set partitions of non_zero keys
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def generate_partitions(elements: tuple[str, ...]) -> list[list[frozenset[str]]]:
        if not elements:
            return [[]]
        first = elements[0]
        rest = elements[1:]
        partitions = []
        for i in range(len(rest) + 1):
            for p in generate_partitions(rest[:i] + rest[i+1:]):
                new_p = [frozenset([first])]
                if i > 0:
                    new_p = [frozenset(rest[:i])] + new_p
                new_p += p
                partitions.append(new_p)
        return partitions

    all_partitions = generate_partitions(tuple(members))

    # Filter partitions where each group sums to zero
    valid_partitions = []
    for partition in all_partitions:
        groups = [set(group) for group in partition]
        valid = True
        for group in groups:
            if sum(non_zero[m] for m in group) != 0:
                valid = False
                break
        if valid:
            valid_partitions.append(groups)

    # Choose the lexicographically smallest partition
    valid_partitions.sort()
    selected_partition = valid_partitions[0]

    # Step 3: Within each group, create transfers
    transfers = []
    for group in selected_partition:
        members_in_group = sorted(group)
        debts = {m: non_zero[m] for m in members_in_group}
        creditors = [m for m in members_in_group if debts[m] > 0]
        debtors = [m for m in members_in_group if debts[m] < 0]

        # Sort creditors and debtors lexicographically
        creditors.sort()
        debtors.sort()

        # Pair smallest debtor with smallest creditor
        while creditors and debtors:
            creditor = creditors[0]
            debtor = debtors[0]
            amount = min(-debts[debtor], debts[creditor])
            transfers.append(Transfer(debtor, creditor, amount))
            debts[creditor] -= amount
            debts[debtor] += amount
            if debts[creditor] == 0:
                creditors.pop(0)
            if debts[debtor] == 0:
                debtors.pop(0)

    # Step 4: Sort transfers by (from_member_id, to_member_id, cents)
    transfers.sort(key=lambda x: (x.from_member_id, x.to_member_id, x.cents))

    return tuple(transfers)

