def remove_last_action(trip: Trip) -> Trip:
    if not trip.actions:
        raise ValueError("empty history")
    return dataclasses.replace(trip, actions=trip.actions[:-1])

impl.undo_last_action:
def undo_last_action(trip_id: str) -> Generator[object, object, Trip]:
    trip_repo = yield from need(TripRepository)
    trip = yield from trip_repo.load_trip(trip_id)

    if trip.closed:
        return (yield from throw(ClosedTripError(trip_id)))

    if not trip.actions:
        return (yield from throw(EmptyHistoryError(trip_id)))

    new_trip = remove_last_action(trip)
    yield from trip_repo.save_trip(new_trip)
    return new_trip

